-- Add a reusable 300-word Chinese professional deck with pre-generated audio.
insert into public.template_decks (slug, name, description, level)
values (
  'xay-dung-cong-trinh-300-tu',
  'Tiếng Trung xây dựng và công trình - 300 từ',
  '300 từ vựng tiếng Trung thực tế về vật liệu, dụng cụ, máy thi công, bản vẽ, kết cấu, điện nước, hoàn thiện, tiến độ, nghiệm thu và an toàn công trình. Mỗi từ có pinyin, nghĩa tiếng Việt, câu ví dụ thực tế và hai audio tạo sẵn.',
  'Xây dựng'
)
on conflict (slug) do update
set
  name = excluded.name,
  description = excluded.description,
  level = excluded.level;

with target_deck as (
  select id
  from public.template_decks
  where slug = 'xay-dung-cong-trinh-300-tu'
)
insert into public.template_cards (
  template_deck_id,
  chinese,
  pinyin,
  meaning_vi,
  example_cn,
  example_pinyin,
  example_vi,
  word_audio_url,
  sentence_audio_url,
  position
)
select
  target_deck.id,
  card.chinese,
  card.pinyin,
  card.meaning_vi,
  card.example_cn,
  card.example_pinyin,
  card.example_vi,
  card.word_audio_url,
  card.sentence_audio_url,
  card.position
from target_deck
cross join (
  values
    ('业主代表', 'yèzhǔ dàibiǎo', 'Đại diện chủ đầu tư', '业主代表定期参加工地会议，监督项目进度和质量。', 'Yèzhǔ dàibiǎo dìngqī cānjiā gōngdì huìyì, jiāndū xiàngmù jìndù hé zhìliàng.', 'Đại diện chủ đầu tư thường xuyên tham gia họp công trường, giám sát tiến độ và chất lượng dự án.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-910e06772d5bd136dd1eea9a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-c486ff56ffc315a722c1f550.mp3', 1),
    ('总承包商', 'zǒng chéngbāo shāng', 'Nhà thầu chính', '总承包商负责协调各分包商，确保施工工序顺利进行。', 'Zǒng chéngbāo shāng fùzé xiédiào gè fēnbāo shāng, quèbǎo shīgōng gōngxù shùnlì jìnxíng.', 'Nhà thầu chính chịu trách nhiệm điều phối các nhà thầu phụ để đảm bảo các công đoạn thi công thuận lợi.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-f8721a0282443ee5324b03cc.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-be4d67990e0db1d641c497da.mp3', 2),
    ('分包单位', 'fēnbāo dānwèi', 'Đơn vị nhà thầu phụ', '分包单位需严格按照技术规范完成各自施工任务。', 'Fēnbāo dānwèi xū yángé ànzhào jìshù guīfàn wánchéng gèzì shīgōng rènwù.', 'Đơn vị nhà thầu phụ phải thực hiện nhiệm vụ thi công chuyên môn theo đúng tiêu chuẩn kỹ thuật.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-00fcce6ab4339a19a448c57d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-eadbb05f6387984e171990e7.mp3', 3),
    ('项目经理', 'xiàngmù jīnglǐ', 'Chỉ huy trưởng dự án', '项目经理每天检查工地安全，确保施工环境符合标准。', 'Xiàngmù jīnglǐ měitiān jiǎnchá gōngdì ānquán, quèbǎo shīgōng huánjìng fúhé biāozhǔn.', 'Chỉ huy trưởng dự án kiểm tra an toàn công trường hàng ngày, đảm bảo môi trường thi công đáp ứng tiêu chuẩn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-11888e7c9cd66fe38cdf2843.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-ff0b81fc626b46ab6574a6ed.mp3', 4),
    ('现场工程师', 'xiànchǎng gōngchéngshī', 'Kỹ sư hiện trường', '现场工程师负责监督施工质量和及时协调现场问题。', 'Xiànchǎng gōngchéngshī fùzé jiāndū shīgōng zhìliàng hé jíshí xiétiáo xiànchǎng wèntí.', 'Kỹ sư hiện trường chịu trách nhiệm giám sát chất lượng thi công và phối hợp xử lý kịp thời các vấn đề tại chỗ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-ca9eed67f80eb1842b18f515.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-6c1e57d595947a2045c0b351.mp3', 5),
    ('施工监理', 'shīgōng jiānlǐ', 'Giám sát thi công', '施工监理定期抽查工程，确保各项指标达到设计要求。', 'Shīgōng jiānlǐ dìngqī chōuchá gōngchéng, quèbǎo gè xiàng zhǐbiāo dáchéng shèjì yāoqiú.', 'Giám sát thi công kiểm tra ngẫu nhiên công trình định kỳ, đảm bảo mọi chỉ tiêu đạt yêu cầu thiết kế.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-3e1ec1ed14f8dd42dc113b40.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-0ce82251435e8171f4a94441.mp3', 6),
