    ('劳务分包', 'láowù fēnbāo', 'Phân công lao động theo hợp đồng phụ', '劳务分包合同明确了工人数量和工期要求。', 'Láowù fēnbāo hétóng míngquèle gōngrén shùliàng hé gōngqī yāoqiú.', 'Hợp đồng phân công lao động quy định số lượng công nhân và thời gian thi công.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-447e076b4a960cd1a18c319d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-f568d57a0be7bcc49532adca.mp3', 29),
    ('奖惩制度', 'jiǎngchéng zhìdù', 'Chế độ khen thưởng và kỷ luật', '制定奖惩制度激励工人提高工作效率和质量。', 'Zhìdìng jiǎngchéng zhìdù jīlì gōngrén tígāo gōngzuò xiàolǜ hé zhìliàng.', 'Thiết lập chế độ khen thưởng và kỷ luật để khuyến khích công nhân nâng cao năng suất và chất lượng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-6ed6e4f9f9300f9ef9eff866.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-e17b54ebdebf53a574275f9b.mp3', 30),
