    ('施工图纸', 'shī gōng tú zhǐ', 'bản vẽ thi công', '施工图纸详细标明了节点和连接方式，便于现场操作。', 'shī gōng tú zhǐ xiáng xì biāo míng le jié diǎn hé lián jiē fāng shì, biàn yú xiàn chǎng cāo zuò.', 'Bản vẽ thi công ghi rõ các nút và phương pháp liên kết, thuận tiện cho thao tác tại công trường.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-4107d712c0a7f852798f4979.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-9d8a9fbb8fd4d5aac5f173a3.mp3', 122),
    ('竣工图', 'jùn gōng tú', 'bản vẽ hoàn công', '竣工图反映了实际施工后的结构尺寸和位置偏差。', 'jùn gōng tú fǎn yìng le shí jì shī gōng hòu de jié gòu chǐ cùn hé wèi zhì piān chā.', 'Bản vẽ hoàn công phản ánh kích thước và sai số vị trí sau thi công thực tế.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-28d131a2b5b79fd1a96dfbcd.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-4accaf4ff66db37483144ee5.mp3', 123),
    ('平面图', 'píng miàn tú', 'mặt bằng', '现场测量人员对照平面图布设控制点定位。', 'xiàn chǎng cè liáng rén yuán duì zhào píng miàn tú bù shè kòng zhì diǎn dìng wèi.', 'Nhân viên đo đạc tại hiện trường sẽ bố trí điểm kiểm soát theo mặt bằng để định vị.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-62cdc55dc575540f71c2feb9.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-5050570381cbc89e0ed8b5ed.mp3', 124),
    ('立面图', 'lì miàn tú', 'mặt đứng', '立面图显示建筑外观和立面装饰的详细尺寸。', 'lì miàn tú xiǎn shì jiàn zhù wài guān hé lì miàn zhuāng shì de xiáng xì chǐ cùn.', 'Mặt đứng thể hiện kích thước chi tiết của ngoại quan và trang trí mặt đứng công trình.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-b77e7c4564d99b6ca3388949.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-ec377687730e0f352a937957.mp3', 125),
    ('剖面图', 'pǒu miàn tú', 'mặt cắt', '剖面图用以揭示建筑内部结构和层高变化。', 'pǒu miàn tú yòng yǐ jiē shì jiàn zhù nèi bù jié gòu hé céng gāo biàn huà.', 'Mặt cắt dùng để trình bày cấu trúc bên trong và sự thay đổi cao độ các tầng của công trình.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-34b4c1f435610bc8008cbfb2.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-cf7f208cfd5740d35cfd38b2.mp3', 126),
    ('构造详图', 'gòu zào xiáng tú', 'chi tiết cấu tạo', '构造详图说明节点连接方式和钢筋配置细节。', 'gòu zào xiáng tú shuō míng jié diǎn lián jiē fāng shì hé gāng jīn pèi zhì xì jié.', 'Chi tiết cấu tạo chỉ rõ phương thức nối các nút và cách bố trí thép cốt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-edc2057e9f9022f4beaee577.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-14953a35e5b0019d7e4591c5.mp3', 127),
    ('图纸比例', 'tú zhǐ bǐ lì', 'tỷ lệ bản vẽ', '绘制图纸时必须严格控制图纸比例保证尺寸准确。', 'huì zhì tú zhǐ shí bì xū yán gé kòng zhì tú zhǐ bǐ lì bǎo zhèng chǐ cùn zhǔn què.', 'Khi vẽ bản vẽ phải kiểm soát tỷ lệ bản vẽ nghiêm ngặt để đảm bảo kích thước chính xác.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-e2f2c0d3efc0ca0e543e579e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-ce30c36d5a65393abb774c3e.mp3', 128),
    ('尺寸标注', 'chǐ cùn biāo zhù', 'kích thước (trên bản vẽ)', '施工人员根据尺寸标注校核现场尺寸符合设计要求。', 'shī gōng rén yuán gēn jù chǐ cùn biāo zhù jiào hé xiàn chǎng chǐ cùn fú hé shè jì yāo qiú.', 'Nhân viên thi công kiểm tra hiện trường theo kích thước trên bản vẽ để đảm bảo theo yêu cầu thiết kế.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-81e585a368137dc0c6a93d4d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-f03fdd56a34ad7185e517e0f.mp3', 129),
    ('高程标高', 'gāo chéng biāo gāo', 'cao độ chuẩn', '测量员利用高程标高确定建筑物各层的垂直位置。', 'cè liáng yuán lì yòng gāo chéng biāo gāo què dìng jiàn zhù wù gè céng de chuí zhí wèi zhì.', 'Nhân viên đo đạc dùng cao độ chuẩn xác định vị trí thẳng đứng các tầng công trình.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-3f1a719b27145486cdb3625d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-774f89d29a10a5032c351095.mp3', 130),
    ('坐标系统', 'zuò biāo xì tǒng', 'hệ tọa độ', '现场定点需要依照坐标系统确定基准点位置。', 'xiàn chǎng dìng diǎn xū yào yī zhào zuò biāo xì tǒng què dìng jī zhǔn diǎn wèi zhì.', 'Việc định vị tại hiện trường cần xác định điểm chuẩn dựa trên hệ tọa độ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-60c5ba26f3160b12ed63f515.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-e1c8ace3510a6088d002991c.mp3', 131),
    ('轴线定位', 'zhóu xiàn dìng wèi', 'tim trục', '工程师在施工现场用激光仪确定轴线定位准确无误。', 'gōng chéng shī zài shī gōng xiàn chǎng yòng jī guāng yí què dìng zhóu xiàn dìng wèi zhǔn què wú wù.', 'Kỹ sư đã dùng máy laser để xác định tim trục chính xác tại công trường.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-618c13ac668b5a9b6372492d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-5e332fa5c1f853db73d901d5.mp3', 132),
    ('测量控制点', 'cè liáng kòng zhì diǎn', 'mốc trắc địa', '测量控制点是后续施工放样的基本参照标志。', 'cè liáng kòng zhì diǎn shì hòu xù shī gōng fàng yàng de jī běn cān zhào biāo zhì.', 'Mốc trắc địa là điểm tham chiếu cơ bản để triển khai lấy dấu thi công tiếp theo.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-38cd391f8caa70e489f50830.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-2f15a9f178ec7f274cbcae9d.mp3', 133),
    ('放样定位', 'fàng yàng dìng wèi', 'định vị (trắc địa)', '工作人员根据设计图纸进行放样定位，保障施工精度。', 'gōng zuò rén yuán gēn jù shè jì tú zhǐ jìn xíng fàng yàng dìng wèi, bǎo zhàng shī gōng jīng dù.', 'Nhân viên căn cứ bản vẽ thiết kế tiến hành định vị lấy dấu nhằm đảm bảo độ chính xác thi công.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-f57867e1f6ba66182b51d8a1.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-34c4306e77500bdd0195d648.mp3', 134),
    ('测量误差', 'cè liáng wù chā', 'sai số đo', '测量误差应控制在设计允许的范围内，确保工程质量。', 'cè liáng wù chā yīng kòng zhì zài shè jì yǔn xǔ de fàn wéi nèi, què bǎo gōng chéng zhì liàng.', 'Sai số đo cần kiểm soát trong phạm vi cho phép của thiết kế để đảm bảo chất lượng công trình.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-bf7a0e6e3cc3fc35d0473ef7.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-262fea670dd1d5ba58ed8445.mp3', 135),
    ('图册', 'tú cè', 'hồ sơ bản vẽ', '现场工程师保管好最新的施工图册，方便随时查阅。', 'xiàn chǎng gōng chéng shī bǎo guǎn hǎo zuì xīn de shī gōng tú cè, fāng biàn suí shí chá yuè.', 'Kỹ sư công trường quản lý tốt hồ sơ bản vẽ thi công mới nhất để thuận tiện tra cứu khi cần.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-78f7dca1f874d9fa5b5360a2.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-3fff796aab37f435ec55d5fd.mp3', 136),
    ('施工放样', 'shī gōng fàng yàng', 'lấy dấu thi công', '施工放样前必须核对图纸，避免偏差影响后续工作。', 'shī gōng fàng yàng qián bì xū hé duì tú zhǐ, bì miǎn piān chā yǐng xiǎng hòu xù gōng zuò.', 'Trước khi lấy dấu thi công phải kiểm tra lại bản vẽ để tránh sai lệch ảnh hưởng công việc sau.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-bbd3cd00c620da71f2cf72bf.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-ebecac8292cc437e6324ffca.mp3', 137),
    ('施工图符号', 'shī gōng tú fú hào', 'ký hiệu bản vẽ thi công', '所有施工人员必须熟悉施工图符号，确保交流无误。', 'suǒ yǒu shī gōng rén yuán bì xū shú xī shī gōng tú fú hào, què bǎo jiāo liú wú wù.', 'Tất cả nhân viên thi công cần thành thạo ký hiệu trên bản vẽ thi công để đảm bảo giao tiếp chính xác.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-2cb88f96798927737d3bc996.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-799947a0477d37531c464b7c.mp3', 138),
    ('结构尺寸', 'jié gòu chǐ cùn', 'kích thước kết cấu', '标注结构尺寸以便制作钢筋及模板准确安装。', 'biāo zhù jié gòu chǐ cùn yǐ biàn zhì zuò gāng jīn jí mù bǎn zhǔn què ān zhuāng.', 'Kích thước kết cấu được ghi chú để sản xuất thép và cốp pha lắp đặt chính xác.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-fe60b0d30aeb2b0365d5d26a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-89ee9178ad14190f43bc0494.mp3', 139),
    ('基准点', 'jī zhǔn diǎn', 'điểm chuẩn', '基准点的稳定性直接影响全场测量的准确性。', 'jī zhǔn diǎn de wěn dìng xì zhí jiē yǐng xiǎng quán chǎng cè liáng de zhǔn què xì.', 'Độ ổn định của điểm chuẩn ảnh hưởng trực tiếp đến độ chính xác đo đạc toàn bộ hiện trường.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-baa5262159cfc652bb676683.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-67946b8806c1cd4ee444c6b8.mp3', 140),
    ('标高点', 'biāo gāo diǎn', 'điểm cao độ', '根据标高点调整施工标尺，保证建筑层高一致。', 'gēn jù biāo gāo diǎn tiáo zhěng shī gōng biāo chǐ, bǎo zhèng jiàn zhù céng gāo yī zhì.', 'Điều chỉnh thước đo thi công theo điểm cao độ để đảm bảo cao độ các tầng đều nhau.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-c6ce2f31edd7e38adf1d5568.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-1dc5910b272211aa7040f9f2.mp3', 141),
    ('网格线', 'wǎng gé xiàn', 'lưới trục', '现场放样时以网格线为参考标识定位构件位置。', 'xiàn chǎng fàng yàng shí yǐ wǎng gé xiàn wéi cān kǎo biāo shí dìng wèi gòu jiàn wèi zhì.', 'Khi lấy dấu tại công trường lấy lưới trục làm chuẩn để định vị vị trí cấu kiện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-f255ba81051fece34e6099b5.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-c3359c8601415bdd0425b676.mp3', 142),
    ('坐标转换', 'zuò biāo zhuǎn huàn', 'chuyển đổi tọa độ', '测量人员需做好坐标转换，确保各项数据一致。', 'cè liáng rén yuán xū zuò hǎo zuò biāo zhuǎn huàn, què bǎo gè xiàng shù jù yī zhì.', 'Nhân viên đo đạc phải thực hiện tốt việc chuyển đổi tọa độ để đảm bảo số liệu đồng nhất.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-e6cd6aff609f0dedc3871a79.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-76ff5fdb7b014aadce64983d.mp3', 143),
    ('测线', 'cè xiàn', 'đo tuyến', '施工测线时严格按设计要求控制线位误差。', 'shī gōng cè xiàn shí yán gé àn shè jì yāo qiú kòng zhì xiàn wèi wù chā.', 'Khi đo tuyến thi công cần kiểm soát nghiêm ngặt sai số vị trí theo yêu cầu thiết kế.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-5f35cb64d5213558abf76bff.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-3de37dd387cf19069cb64ac1.mp3', 144),
    ('剖面标高', 'pǒu miàn biāo gāo', 'cao độ mặt cắt', '剖面标高用以描述建筑各部位的高度变化情况。', 'pǒu miàn biāo gāo yòng yǐ miáo shù jiàn zhù gè bù wèi de gāo dù biàn huà qíng kuàng.', 'Cao độ mặt cắt dùng để mô tả sự thay đổi độ cao các bộ phận trong công trình.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-403fac392831eac2250afc31.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-21949de88abc50a43fdd8b7b.mp3', 145),
    ('设计标高', 'shè jì biāo gāo', 'cao độ thiết kế', '施工前根据设计标高完成基坑开挖工作。', 'shī gōng qián gēn jù shè jì biāo gāo wán chéng jī kēng kāi wā gōng zuò.', 'Trước thi công đào hố móng theo cao độ thiết kế đã định trước.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-533ec04bb535d0f7ca2fc504.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-8413937473e23fc9726cb413.mp3', 146),
    ('放线仪', 'fàng xiàn yí', 'thiết bị bắn tia lấy dấu', '使用放线仪精准定位轴线，确保施工位置准确。', 'shǐ yòng fàng xiàn yí jīng zhǔn dìng wèi zhóu xiàn, què bǎo shī gōng wèi zhì zhǔn què.', 'Dùng thiết bị bắn tia lấy dấu để định vị tim trục chính xác, đảm bảo vị trí thi công.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-cd353cdbbe5f3572fc042530.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-aceb57dbbe1c5b7120ebbffc.mp3', 147),
    ('测绘标识', 'cè huì biāo shí', 'ký hiệu trắc địa', '测绘标识清晰标注，方便现场工作人员识别和操作。', 'cè huì biāo shí qīng xī biāo zhù, fāng biàn xiàn chǎng gōng zuò rén yuán shí bié hé cāo zuò.', 'Ký hiệu trắc địa được ghi rõ ràng giúp nhân viên hiện trường nhận biết và thao tác thuận tiện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-32f43f3bb43bc765a2f06557.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-96cced224edf7b1540cb7af8.mp3', 148),
    ('基线测量', 'jī xiàn cè liáng', 'đo baseline (đường cơ sở)', '基线测量为工程定位提供精确参照基准。', 'jī xiàn cè liáng wèi gōng chéng dìng wèi tí gōng jīng què cān zhào jī zhǔn.', 'Đo baseline cung cấp điểm tham chiếu chính xác cho việc định vị công trình.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-32cb8df543e9e5e07a5e4f3b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-1387694dc7424a023b637487.mp3', 149),
    ('观测点', 'guān cè diǎn', 'điểm quan trắc', '在施工现场设立观测点监测变形及沉降情况。', 'zài shī gōng xiàn chǎng shè lì guān cè diǎn jiān cè biàn xíng jí chén jiàng qíng kuàng.', 'Đặt điểm quan trắc tại công trường để giám sát biến dạng và lún nền.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-70376817024677f39399e813.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-973c3709406008cf918db4f8.mp3', 150),
    ('基坑开挖', 'jī kēng kāi wā', 'đào hố móng', '施工队伍正在进行基坑开挖，确保土方符合设计深度和坡度要求。', 'shī gōng duì wǔ zhèng zài jìn xíng jī kēng kāi wā, què bǎo tǔ fāng fú hé shè jì shēn dù hé pō dù yāo qiú.', 'Đội thi công đang tiến hành đào hố móng, đảm bảo đất đúng độ sâu và độ dốc thiết kế.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-44590183d9232773fce0527f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-50420b3d04ab51c270b50445.mp3', 151),
    ('桩基处理', 'zhuāng jī chǔ lǐ', 'xử lý nền cọc', '在桩基处理阶段，必须检测每根桩的承载力是否合格。', 'zài zhuāng jī chǔ lǐ jiē duàn, bì xū jiǎn cè měi gēn zhuāng de chéng zài lì shì fǒu hé gé.', 'Ở giai đoạn xử lý nền cọc, phải kiểm tra tải trọng của từng cọc có đạt yêu cầu hay không.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-8384f9cfc541e6180d1c85fc.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-38ac418499540f968a29eb89.mp3', 152),
    ('单桩承载力', 'dān zhuāng chéng zài lì', 'tải trọng chịu lực của cọc đơn', '设计需要考虑单桩承载力，以保证基础的稳定性。', 'shè jì xū yào kǎo lǜ dān zhuāng chéng zài lì, yǐ bǎo zhèng jī chǔ de wěn dìng xìng.', 'Thiết kế cần xem xét tải trọng chịu lực của cọc đơn để đảm bảo tính ổn định nền móng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-58978176dec83d5f8ca31d32.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-ba95bf6132ba71ceaa22976a.mp3', 153),
    ('桩基静力压桩', 'zhuāng jī jìng lì yā zhuāng', 'ép cọc tĩnh lực', '施工现场采用桩基静力压桩设备确保桩基垂直且受力均匀。', 'shī gōng xiàn chǎng cǎi yòng zhuāng jī jìng lì yā zhuāng shè bèi què bǎo zhuāng jī chuí zhí qiě shòu lì jūn yún.', 'Công trường sử dụng thiết bị ép cọc tĩnh lực để đảm bảo cọc thẳng đứng và chịu lực đều.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-2872e4e24d515a9f5e4bf2a7.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-f7a53cbd05c5462e541cc6a2.mp3', 154),
    ('承台施工', 'chéng tái shī gōng', 'thi công đài cọc', '承台施工须按照设计图纸布置钢筋并确保混凝土养护。', 'chéng tái shī gōng xū àn zhào shè jì tú zhǐ bù zhì gāng jīn bìng què bǎo hùn níng tǔ yǎng hù.', 'Thi công đài cọc phải bố trí thép theo bản vẽ thiết kế và đảm bảo bảo dưỡng bê tông.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-8ef634e5414edb6dc741b206.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-6f6f7ad3a4d290d79b2908cb.mp3', 155),
    ('梁板体系', 'liáng bǎn tǐ xì', 'hệ dầm sàn', '梁板体系设计合理可以有效分散楼层荷载。', 'liáng bǎn tǐ xì shè jì hé lǐ kě yǐ yǒu xiào fēn sàn lóu céng hè zǎi.', 'Thiết kế hệ dầm sàn hợp lý có thể phân tán tải trọng sàn hiệu quả.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-d99ae9411951056c12d5799f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-029a5785fc9ac7ac46705e43.mp3', 156),
    ('承重墙', 'chéng zhòng qiáng', 'tường chịu lực', '施工过程中承重墙的位置不可随意变更，以保证结构安全。', 'shī gōng guò chéng zhōng chéng zhòng qiáng de wèi zhì bù kě suí yì biàn gēng, yǐ bǎo zhèng jié gòu ān quán.', 'Trong quá trình thi công, không được tự ý thay đổi vị trí tường chịu lực để đảm bảo an toàn kết cấu.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-9ca6b3979bc1111f382711d6.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-44cef96dacacd320ad57438f.mp3', 157),
    ('地基加固', 'dì jī jiā gù', 'gia cố nền móng', '发现地基承载力不足，必须立即进行地基加固处理。', 'fā xiàn dì jī chéng zài lì bù zú, bì xū lì jí jìn xíng dì jī jiā gù chǔ lǐ.', 'Phát hiện tải trọng nền móng không đủ phải tiến hành gia cố ngay.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-591830990ed48a02a3e37e15.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-8565a5b3fe73e5ff0a507f8d.mp3', 158),
    ('防裂缝措施', 'fáng liè fèng cuò shī', 'biện pháp chống nứt nẻ', '梁与柱接口处要采取防裂缝措施，防止结构损坏。', 'liáng yǔ zhù jiē kǒu chù yào cǎi qǔ fáng liè fèng cuò shī, fáng zhǐ jié gòu sǔn huài.', 'Vị trí nối giữa dầm và cột cần thực hiện biện pháp chống nứt để ngăn hư hỏng kết cấu.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-8e59d34f9614b205de37195d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-5567213ff7cf20452c8a5319.mp3', 159),
    ('伸缩缝设计', 'shēn suō fèng shè jì', 'thiết kế khe co giãn', '建筑物层间的伸缩缝设计必须符合抗震规范要求。', 'jiàn zhú wù céng jiān de shēn suō fèng shè jì bì xū fú hé kàng zhèn guī fàn yāo qiú.', 'Thiết kế khe co giãn giữa các tầng của công trình phải đáp ứng tiêu chuẩn chống động đất.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-53a85092a310881da08a67fe.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-5feb8e132b4af6bd9850823d.mp3', 160),
    ('基础垫层', 'jī chǔ diàn céng', 'lớp đệm móng', '基础垫层施工要压实，防止不均匀沉降。', 'jī chǔ diàn céng shī gōng yào yā shí, fáng zhǐ bù jūn yún chén jiàng.', 'Thi công lớp đệm móng phải đầm chặt để tránh lún không đều.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-3df078c4df4e9dd3ec2b31c5.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-679660fd57a82412210242e9.mp3', 161),
    ('独立基础', 'dú lì jī chǔ', 'móng đơn', '低层建筑多采用独立基础以减少土方开挖量。', 'dī céng jiàn zhù duō cǎi yòng dú lì jī chǔ yǐ jiǎn shǎo tǔ fāng kāi wā liàng.', 'Công trình thấp tầng thường dùng móng đơn để giảm khối lượng đào đất.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-88be6dcc5507ae54d5951002.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-0041e7ad3a59997c27be02b3.mp3', 162),
    ('条形基础', 'tiáo xíng jī chǔ', 'móng băng', '条形基础必须连续浇筑，保证整体受力效果。', 'tiáo xíng jī chǔ bì xū lián xù jiāo zhù, bǎo zhèng zhěng tǐ shòu lì xiào guǒ.', 'Móng băng phải đổ liên tục để đảm bảo chịu lực đồng nhất.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-6d14f44c97c95079ead12fdc.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-fd0c5dc3e9466cecbb2f1009.mp3', 163),
    ('筏板基础', 'fá bǎn jī chǔ', 'móng bè', '软土地基采用筏板基础可以有效分散荷载。', 'ruǎn tǔ dì jī cǎi yòng fá bǎn jī chǔ kě yǐ yǒu xiào fēn sàn hè zǎi.', 'Nền đất yếu sử dụng móng bè để phân tán tải trọng hiệu quả.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-10933a643579e92bff3ced51.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-7c78961e3467a648bcd0cbae.mp3', 164),
    ('柱脚防腐', 'zhù jiǎo fáng fǔ', 'chống ăn mòn chân cột', '柱脚防腐处理能延长结构使用寿命，防止腐蚀损坏。', 'zhù jiǎo fáng fǔ chǔ lǐ néng yán cháng jié gòu shǐ yòng shòu mìng, fáng zhǐ fǔ shí sǔn huài.', 'Xử lý chống ăn mòn chân cột giúp kéo dài tuổi thọ kết cấu và tránh hư hại do ăn mòn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-5e087f3b9ba9fbe37b43cbeb.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-d69e32e1dc0d31560f24a3b4.mp3', 165),
    ('地基沉降控制', 'dì jī chén jiàng kòng zhì', 'kiểm soát lún nền móng', '施工过程中要严格进行地基沉降控制，防止结构变形。', 'shī gōng guò chéng zhōng yào yán gé jìn xíng dì jī chén jiàng kòng zhì, fáng zhǐ jié gòu biàn xíng.', 'Trong quá trình thi công phải kiểm soát nghiêm ngặt lún nền móng để tránh biến dạng kết cấu.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-8f5969f663275b8ceb416d6e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-6472a31003398aee34bbef9d.mp3', 166),
    ('地下连续墙', 'dì xià lián xù qiáng', 'tường vây thi công ngầm', '地下连续墙施工用于深基坑支护，保障开挖安全。', 'dì xià lián xù qiáng shī gōng yòng yú shēn jī kēng zhī hù, bǎo zhàng kāi wā ān quán.', 'Thi công tường vây ngầm dùng để chống giữ hố móng sâu đảm bảo an toàn đào đất.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-48767eeab0305a82c95d8502.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-9866f3cdfda6b6fba1f92172.mp3', 167),
    ('钢筋笼安装', 'gāng jīn lóng ān zhuāng', 'lắp đặt giàn thép', '钢筋笼安装必须按图纸要求定位，并绑扎牢固。', 'gāng jīn lóng ān zhuāng bì xū àn tú zhǐ yāo qiú dìng wèi, bìng bǎ láo gù.', 'Lắp đặt giàn thép phải định vị theo bản vẽ và buộc chắc chắn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-21485017d71d748934cac6a3.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-da6a9c82b4304dde2fd5fd01.mp3', 168),
    ('混凝土浇筑', 'hùn níng tǔ jiāo zhù', 'đổ bê tông', '混凝土浇筑时需连续作业，防止冷缝产生。', 'hùn níng tǔ jiāo zhù shí xū lián xù zuò yè, fáng zhǐ lěng fèng chǎn shēng.', 'Khi đổ bê tông cần thi công liên tục để tránh xuất hiện vết ngừng thi công.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-0783b7bfde4a3c8c3a79963c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-3c88f70195b9142f2b94c227.mp3', 169),
    ('模板支撑', 'mù bǎn zhī chēng', 'giàn giáo cốp pha', '模板支撑结构必须稳固，以保证混凝土成型质量。', 'mù bǎn zhī chēng jié gòu bì xū wěn gù, yǐ bǎo zhèng hùn níng tǔ chéng xíng zhì liàng.', 'Kết cấu giàn giáo cốp pha phải chắc chắn để đảm bảo chất lượng bê tông định hình.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-96858580bd46fdae8697eaab.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-e9e89b6bc281ae5b89258eda.mp3', 170),
    ('钢结构焊接', 'gāng jié gòu hàn jiē', 'hàn kết cấu thép', '钢结构焊接点需要经过无损检测确认质量。', 'gāng jié gòu hàn jiē diǎn xū yào jīng guò wú sǔn jiǎn cè quèrèn zhì liàng.', 'Các điểm hàn kết cấu thép cần kiểm tra chất lượng bằng phương pháp không phá hủy.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-76bc47a88289563f0490242c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-c16e3a15cff76edde5ab9f4e.mp3', 171),
    ('地基承载力检测', 'dì jī chéng zài lì jiǎn cè', 'kiểm tra tải trọng nền móng', '工程开工前必须完成地基承载力检测报告。', 'gōng chéng kāi gōng qián bì xū wán chéng dì jī chéng zài lì jiǎn cè bào gào.', 'Trước khi khởi công, phải hoàn thành báo cáo kiểm tra tải trọng nền móng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-9f6e1b22ad76171a3cea5f3a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-61b4f0ae04896179319ac619.mp3', 172),
    ('结构加固设计', 'jié gòu jiā gù shè jì', 'thiết kế gia cố kết cấu', '老旧建筑需要结构加固设计以提高安全性能。', 'lǎo jiù jiàn zhù xū yào jié gòu jiā gù shè jì yǐ tí gāo ān quán xìng néng.', 'Công trình cũ cần thiết kế gia cố kết cấu để nâng cao an toàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-284599629fd8c9fba3c6cacf.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-5b4f1528a1e3e12a7664b585.mp3', 173),
    ('垂直度控制', 'chuí zhí dù kòng zhì', 'kiểm soát độ thẳng đứng', '柱子施工时必须严格垂直度控制，确保结构稳定。', 'zhù zi shī gōng shí bì xū yán gé chuí zhí dù kòng zhì, què bǎo jié gòu wěn dìng.', 'Khi thi công cột bắt buộc phải kiểm soát nghiêm ngặt độ thẳng đứng để bảo đảm kết cấu ổn định.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-0e2fd0acf6ee50d4e1f70acf.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-0b00fbdabefedcdc0765628e.mp3', 174),
    ('砂浆填缝', 'shā jiāng tián fèng', 'chít vữa trám khe', '结构缝隙使用砂浆填缝以防止水分渗入。', 'jié gòu fèng xì shǐ yòng shā jiāng tián fèng yǐ fáng zhǐ shuǐ fèn shèn rù.', 'Trám khe cấu kiện bằng vữa để ngăn ngấm nước.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-4d9d2ac3c8392fcddf1b7700.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-81cf462c979371929d4c7b64.mp3', 175),
    ('混凝土养护', 'hùn níng tǔ yǎng hù', 'bảo dưỡng bê tông', '混凝土浇筑完成后需要及时进行混凝土养护。', 'hùn níng tǔ jiāo zhù wán chéng hòu xū yào jí shí jìn xíng hùn níng tǔ yǎng hù.', 'Sau khi đổ bê tông xong phải bảo dưỡng kịp thời.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-be218667cf0422df6b5b5280.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-173a6da33284f279d9ef6e4e.mp3', 176),
    ('基槽开挖', 'jī cáo kāi wā', 'đào rãnh móng', '基槽开挖必须达到设计标高并清理杂物。', 'jī cáo kāi wā bì xū dá dào shè jì biāo gāo bìng qīng lǐ zá wù.', 'Đào rãnh móng phải đạt cao độ thiết kế và dọn sạch tạp vật.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-925d7bf5a518885a1f3f0699.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-d9799f286de94559c42442bd.mp3', 177),
    ('预应力筋安装', 'yù yìng lì jīn ān zhuāng', 'lắp đặt dây thép dự ứng lực', '预应力筋安装必须精准张拉，确保结构受力均匀。', 'yù yìng lì jīn ān zhuāng bì xū jīng zhǔn zhāng lā, què bǎo jié gòu shòu lì jūn yún.', 'Lắp đặt dây thép dự ứng lực phải căng chính xác để đảm bảo chịu lực đều.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-01b1e0ab3702a2ea9e56776a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-371b7eace1273c1747b42978.mp3', 178),
    ('基础防水层', 'jī chǔ fáng shuǐ céng', 'lớp chống thấm móng', '基础防水层施工要连续密实防止地下水渗透。', 'jī chǔ fáng shuǐ céng shī gōng yào lián xù mì shí fáng zhǐ dì xià shuǐ shèn tòu.', 'Thi công lớp chống thấm móng phải liền mạch và kín để ngăn nước ngầm thấm.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-6fa90e21c1cd412c087dba02.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-9bb95e1a48d048ead38050b6.mp3', 179),
    ('基础钢筋绑扎', 'jī chǔ gāng jīn bǎng zā', 'buộc thép móng', '基础钢筋绑扎需严格按照设计节点进行。', 'jī chǔ gāng jīn bǎng zā xū yán gé àn zhào shè jì jié diǎn jìn xíng.', 'Buộc thép móng phải thực hiện nghiêm túc theo các mấu nối thiết kế.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-2d42336bb1dc7dfbc1bab41c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-c6ae05d8b1a541f3ac273051.mp3', 180),
    ('钢筋切割', 'gāng jīn qiē gē', 'Cắt thép', '施工队用钢筋切割机准确完成了钢筋切割任务。', 'shī gōng duì yòng gāng jīn qiē gē jī zhǔn què wán chéng le gāng jīn qiē gē rèn wù.', 'Đội thi công sử dụng máy cắt thép để cắt thép chính xác.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-7f998c12335598801b1b4ba6.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-50fb2461ebcd5ca9224de5f6.mp3', 181),
    ('钢筋弯曲', 'gāng jīn wān qū', 'Uốn thép', '钢筋弯曲工艺确保了结构的设计形状和强度要求。', 'gāng jīn wān qū gōng yì què bǎo le jié gòu de shè jì xíng zhuàng hé qiáng dù yāo qiú.', 'Quy trình uốn thép đảm bảo hình dạng và yêu cầu chịu lực của cấu trúc.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-18e16f5e5aec5970e4339829.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-d2568ce66c5092b595e0e0bd.mp3', 182),
    ('钢筋绑扎', 'gāng jīn bǎng zā', 'Buộc thép', '工人正在进行钢筋绑扎以保证钢筋笼的牢固。', 'gōng rén zhèng zài jìn xíng gāng jīn bǎng zā yǐ bǎo zhèng gāng jīn lóng de láo gù.', 'Công nhân đang buộc thép để đảm bảo giằng thép chắc chắn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-54dd1868825b9834d8e993d8.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-26cfacff9f646dbe0ce69745.mp3', 183),
    ('保护层', 'bǎo hù céng', 'Lớp bê tông bảo vệ (lớp bảo vệ cốt thép)', '保护层厚度必须符合设计要求，避免钢筋锈蚀。', 'bǎo hù céng hòu dù bì xū fú hé shè jì yāo qiú, bì miǎn gāng jīn xiù shí.', 'Độ dày lớp bảo vệ phải đáp ứng thiết kế để tránh thép bị gỉ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-12130fcfbd74be7127508bda.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-fae8200f7e2684f1edf20c20.mp3', 184),
    ('模板安装', 'mú bǎn ān zhuāng', 'Lắp đặt cốp pha', '模板安装完成后，必须检查尺寸和垂直度。', 'mú bǎn ān zhuāng wán chéng hòu, bì xū jiǎn chá chǐ cùn hé chuí zhí dù.', 'Sau khi lắp cốp pha, phải kiểm tra kích thước và độ thẳng đứng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-a621f0dfe0d3f627bd7a97e4.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-ec92f1859ae5c12c4976dbce.mp3', 185),
    ('支撑系统', 'zhī chēng xì tǒng', 'Hệ thống chống cốp pha', '支撑系统确保模板在混凝土浇筑时不会变形。', 'zhī chēng xì tǒng què bǎo mú bǎn zài hùn níng tǔ jiāo zhù shí bù huì biàn xíng.', 'Hệ thống chống cốp pha đảm bảo cốp pha không bị biến dạng lúc đổ bê tông.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-a809f99129ff9c493a429e85.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-a86d37eb0fb90d17aaaabea8.mp3', 186),
    ('施工缝', 'shī gōng fèng', 'Mạch ngừng', '施工缝处必须处理得当，防止出现裂缝和渗水。', 'shī gōng fèng chù bì xū chǔ lǐ dé dàng, fáng zhǐ chū xiàn liè fèng hé shèn shuǐ.', 'Vị trí mạch ngừng phải được xử lý đúng cách để tránh nứt và thấm nước.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-6ef35006b6d3b31460cff76f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-0667ac4f563dd9fb3658956e.mp3', 187),
    ('拆模', 'chāi mó', 'Tháo cốp pha', '拆模前，必须确认混凝土已达到设计强度。', 'chāi mó qián, bì xū quèrèn hùn níng tǔ yǐ dádào shè jì qiáng dù.', 'Trước khi tháo cốp pha, phải xác nhận bê tông đã đạt cường độ thiết kế.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-f025096e4bb597074adc7c61.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-fa6819e13d44a38b01c0c5e5.mp3', 188),
    ('砌筑墙体', 'qì zhù qiáng tǐ', 'Xây tường', '施工人员根据图纸规范进行砌筑墙体工作。', 'shī gōng rén yuán gēn jù tú zhǐ guī fàn jìn xíng qì zhù qiáng tǐ gōng zuò.', 'Công nhân thi công xây tường theo đúng quy chuẩn bản vẽ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-3c3c797a6d398384ace856fb.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-61497c53a4e7635760e328d7.mp3', 189),
    ('灰缝', 'huī fèng', 'Mạch vữa', '为了保证墙体质量，灰缝必须均匀且密实。', 'wèi le bǎo zhèng qiáng tǐ zhì liàng, huī fèng bì xū jūn yún qiě mì shí.', 'Để đảm bảo chất lượng tường, mạch vữa phải đều và đặc chắc.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-09d84d63a4a3b02123b11ea4.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-0269d88973d2e0217cbba07e.mp3', 190),
    ('抹灰', 'mǒ huī', 'Trát tường', '抹灰工序完成后，墙面应光滑平整。', 'mǒ huī gōng xù wán chéng hòu, qiáng miàn yīng guāng huá píng zhěng.', 'Sau khi trát, bề mặt tường phải mịn và bằng phẳng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-835097ad0d14821a3d7d0185.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-90dfed79d6528bc6c0e5330e.mp3', 191),
    ('表面平整度', 'biǎo miàn píng zhěng dù', 'Độ phẳng bề mặt', '验收时需测量混凝土表面平整度，确保符合规范。', 'yàn shōu shí xū cè liáng hùn níng tǔ biǎo miàn píng zhěng dù, què bǎo fú hé guī fàn.', 'Khi nghiệm thu cần đo độ phẳng bề mặt bê tông theo quy chuẩn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-f71c36fe13b1134642a91f43.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-bef6043be5c3e88dcacad437.mp3', 192),
    ('钢筋连接', 'gāng jīn lián jiē', 'Liên kết thép', '钢筋连接处必须焊接牢固，保证受力一致。', 'gāng jīn lián jiē chù bì xū hàn jiē láo gù, bǎo zhèng shòu lì yī zhì.', 'Phần nối thép phải được hàn chắc chắn để đảm bảo chịu lực đồng đều.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-ca6ec0f263326a17be1dd04d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-3a8b7edf10dab6b1a54a87a0.mp3', 193),
    ('钢筋笼制作', 'gāng jīn lóng zhì zuò', 'Gia công lắp dựng cốt thép (làm giằng thép)', '钢筋笼制作过程中须严格遵守图纸尺寸和绑扎规范。', 'gāng jīn lóng zhì zuò guò chéng zhōng xū yán gé zūn shǒu tú zhǐ chǐ cùn hé bǎng zā guī fàn.', 'Trong quá trình làm giằng thép phải tuân thủ kích thước và quy chuẩn buộc thép theo bản vẽ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-8ac5d2b6a87addcb084fd62d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-ebe23c9971ac5eec186901ec.mp3', 194),
    ('模板支架', 'mú bǎn zhī jià', 'Giá đỡ cốp pha', '模板支架质量直接影响模板的稳定性和安全性。', 'mú bǎn zhī jià zhì liàng zhí jiē yǐng xiǎng mú bǎn de wěn dìng xìng hé ān quán xìng.', 'Chất lượng giá đỡ cốp pha ảnh hưởng trực tiếp đến sự ổn định và an toàn của cốp pha.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-a81155141d6ce7ef8ae002eb.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-358dbb8ef0746f111bdd57c3.mp3', 195),
    ('浇筑缝处理', 'jiāo zhù fèng chǔ lǐ', 'Xử lý mạch ngừng đổ bê tông', '浇筑缝处理不当会导致混凝土结构裂缝。', 'jiāo zhù fèng chǔ lǐ bù dàng huì dǎo zhì hùn níng tǔ jié gòu liè fèng.', 'Xử lý mạch ngừng kém sẽ gây ra nứt cấu trúc bê tông.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-98789867b33623b1fc5d597d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-609ced6e650316018d49eb7c.mp3', 196),
    ('养护温度', 'yǎng hù wēn dù', 'Nhiệt độ bảo dưỡng', '混凝土养护期间，应控制养护温度保持适宜。', 'hùn níng tǔ yǎng hù qī jiān, yīng kòng zhì yǎng hù wēn dù bǎo chí shì yí.', 'Trong thời gian bảo dưỡng bê tông cần kiểm soát nhiệt độ bảo dưỡng phù hợp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-963392360befa0a46bc1c8f4.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-20e4091feca8e234fd2bbb1d.mp3', 197),
    ('拆模时间', 'chāi mó shí jiān', 'Thời gian tháo cốp pha', '拆模时间应根据混凝土强度和环境条件合理安排。', 'chāi mó shí jiān yīng gēn jù hùn níng tǔ qiáng dù hé huán jìng tiáo jiàn hé lǐ ān pái.', 'Thời gian tháo cốp pha phải được sắp xếp hợp lý dựa vào cường độ bê tông và điều kiện môi trường.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-a8fd5f3444459043500ca519.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-c632b8d3caa94469ef456c5d.mp3', 198),
    ('砌筑砂浆', 'qì zhù shā jiāng', 'Vữa xây (vữa ốp, mạch vữa)', '砌筑砂浆配比需准确，确保墙体强度和耐久性。', 'qì zhù shā jiāng pèi bǐ xū zhǔn què, què bǎo qiáng tǐ qiáng dù hé nài jiǔ xìng.', 'Tỷ lệ trộn vữa xây phải chính xác để đảm bảo độ bền và chắc tường.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-70516ef3b0d49ad090e74b3b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-c3c993090991e829c2a43655.mp3', 199),
    ('抹灰层厚度', 'mǒ huī céng hòu dù', 'Độ dày lớp trát', '抹灰层厚度应均匀，防止墙面开裂。', 'mǒ huī céng hòu dù yīng jūn yún, fáng zhǐ qiáng miàn kāi liè.', 'Độ dày lớp trát phải đều để tránh tường bị nứt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-93c316e580fbffd7c0276369.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-76f0e247ff5623b336bea356.mp3', 200),
    ('墙面平整度', 'qiáng miàn píng zhěng dù', 'Độ phẳng bề mặt tường', '检查墙面平整度，确保粉刷施工质量。', 'jiǎn chá qiáng miàn píng zhěng dù, què bǎo fěn shuā shī gōng zhì liàng.', 'Kiểm tra độ phẳng tường để đảm bảo chất lượng thi công hoàn thiện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-46feaf79b57b695ced45c1cb.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-032c02cf44712fee5c3fae98.mp3', 201),
    ('钢筋锚固', 'gāng jīn máo gù', 'Neo thép', '钢筋锚固长度满足规范要求，保证结构安全。', 'gāng jīn máo gù cháng dù mǎn zú guī fàn yāo qiú, bǎo zhèng jié gòu ān quán.', 'Chiều dài neo thép đáp ứng tiêu chuẩn đảm bảo an toàn kết cấu.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-9dea27f5886038920e670707.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-4a0f2d80740a02786797fe88.mp3', 202),
    ('模板拼装', 'mú bǎn pīn zhuāng', 'Ghép cốp pha', '模板拼装前应清理干净，保证拼接严密。', 'mú bǎn pīn zhuāng qián yīng qīng lǐ gān jìng, bǎo zhèng pīn jiē yán mì.', 'Trước khi ghép cốp pha phải dọn sạch để đảm bảo mối ghép kín khít.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-4cc61d76d20749c81cbaa20d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-006fedecffa7ff6da3de9e07.mp3', 203),
    ('混凝土试块', 'hùn níng tǔ shì kuài', 'Khối thử bê tông', '取样制作混凝土试块，用于强度检测。', 'qǔ yàng zhì zuò hùn níng tǔ shì kuài, yòng yú qiáng dù jiǎn cè.', 'Lấy mẫu làm khối thử bê tông để kiểm tra cường độ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-3e66d4dd75160bd41813048b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-100ee2f26b73e8f29b842e8a.mp3', 204),
    ('钢筋防锈处理', 'gāng jīn fáng xiù chǔ lǐ', 'Xử lý chống rỉ thép', '钢筋防锈处理后才能进行绑扎作业。', 'gāng jīn fáng xiù chǔ lǐ hòu cáinéng jìn xíng bǎng zā zuò yè.', 'Phải xử lý chống rỉ sạch thép trước khi buộc thép.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-81b00e08387e1ee5bbbf0ce2.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-a22a49704be2e8c85c8de490.mp3', 205),
    ('混凝土振动器', 'hùn níng tǔ zhèn dòng qì', 'Máy đầm bê tông', '使用混凝土振动器振实混凝土，确保密实度。', 'shǐ yòng hùn níng tǔ zhèn dòng qì zhèn shí hùn níng tǔ, què bǎo mì shí dù.', 'Dùng máy đầm bê tông để đầm chặt bê tông đảm bảo đặc chắc.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-0c32dba79d7b6d8104e02357.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-3295ca630969b7e24dffaa88.mp3', 206),
    ('钢筋切割机', 'gāng jīn qiē gē jī', 'máy cắt thép', '施工现场正在使用钢筋切割机进行钢筋切割任务以确保尺寸精确。', 'shī gōng xiàn chǎng zhèng zài shǐ yòng gāng jīn qiē gē jī jìn xíng gāng jīn qiē gē rèn wù yǐ què bǎo chǐ cùn jīng què.', 'Công trường đang sử dụng máy cắt thép để thực hiện nhiệm vụ cắt thép đảm bảo kích thước chính xác.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-2e89597553ba7e25a3114068.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-d44f6901f0f858ce01603a16.mp3', 207),
    ('钢筋弯曲机', 'gāng jīn wān qū jī', 'máy uốn thép', '工人用钢筋弯曲机调整钢筋的弯曲角度符合设计要求。', 'gōng rén yòng gāng jīn wān qū jī tiáo zhěng gāng jīn de wān qū jiǎo dù fú hé shè jì yāo qiú.', 'Công nhân dùng máy uốn thép chỉnh sửa góc uốn thép phù hợp yêu cầu thiết kế.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-b8acd50d19b3a3805ff5851e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-6d2c020baf512e4e2597774d.mp3', 208),
    ('钢筋绑扎钩', 'gāng jīn bǎng zā gōu', 'móc buộc thép', '使用钢筋绑扎钩确保钢筋牢固固定，以防变形和移位。', 'shǐ yòng gāng jīn bǎng zā gōu què bǎo gāng jīn láo gù gù dìng, yǐ fáng biàn xíng hé yí wèi.', 'Sử dụng móc buộc thép để đảm bảo thép được cố định chắc chắn, tránh biến dạng và dịch chuyển.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-09c438ad09cd770268294766.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-f2246a8b49f5289d05851d3b.mp3', 209),
    ('保护层厚度', 'bǎo hù céng hòu dù', 'độ dày lớp bê tông bảo vệ', '现场验收保护层厚度，以确保钢筋不受腐蚀影响。', 'xiàn chǎng yàn shōu bǎo hù céng hòu dù, yǐ què bǎo gāng jīn bù shòu fǔ shí yǐng xiǎng.', 'Nghiệm thu tại công trường độ dày lớp bê tông bảo vệ để đảm bảo thép không bị ảnh hưởng bởi ăn mòn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-f884f2cab873c31b0361cb3b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-6cb65225bfb2cb8e3ec18861.mp3', 210),
    ('穿线管', 'chuān xiàn guǎn', 'ống luồn dây điện', '现场工人正在用穿线管保护电线，防止机械损伤。', 'xiàn chǎng gōng rén zhèng zài yòng chuān xiàn guǎn bǎo hù diàn xiàn, fáng zhǐ jī xiè sǔn shāng.', 'Công nhân công trường đang dùng ống luồn dây để bảo vệ dây điện, tránh hư hại do máy móc.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-1cd0438b7928bd7d517411be.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-f50acf5efda57ae948b9b590.mp3', 211),
    ('电缆', 'diàn lǎn', 'dây điện, cáp điện', '这个项目要求用防火电缆连接配电箱，确保安全。', 'zhè ge xiàng mù yāo qiú yòng fáng huǒ diàn lǎn lián jiē pèi diàn xiāng, què bǎo ān quán.', 'Dự án này yêu cầu dùng dây điện chống cháy để nối tủ điện, đảm bảo an toàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-e14a5acc835dc76e3aba3798.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-e4cd72a7a33f1b1ecac1ecb3.mp3', 212),
    ('配电箱', 'pèi diàn xiāng', 'tủ điện phân phối', '施工队正在安装新的配电箱以满足用电需求。', 'shī gōng duì zhèng zài ān zhuāng xīn de pèi diàn xiāng yǐ mǎn zú yòng diàn xū qiú.', 'Đội thi công đang lắp đặt tủ điện mới để đáp ứng nhu cầu sử dụng điện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-e11203119a116ff4b7d72026.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-94ccbf527e271a282386c5f8.mp3', 213),
    ('断路器', 'duàn lù qì', 'cầu dao điện, aptomat', '断路器需要定期检查，防止电路过载引发事故。', 'duàn lù qì xū yào dìng qī jiǎn chá, fáng zhǐ diàn lù guò zài yǐn fā shì gù.', 'Cầu dao điện cần được kiểm tra định kỳ để tránh quá tải mạch gây tai nạn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-8f0baa16f447530a62fe1782.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-cd276d0c5a222fd2e0ce67c0.mp3', 214),
    ('接地装置', 'jiē dì zhuāng zhì', 'thiết bị tiếp địa', '所有电气设备必须安装接地装置保证安全。', 'suǒ yǒu diàn qì shè bèi bì xū ān zhuāng jiē dì zhuāng zhì bǎo zhèng ān quán.', 'Tất cả thiết bị điện phải lắp thiết bị tiếp địa để đảm bảo an toàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-a39074ded868cb9c1195c136.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-d6d671bb9eccc24b1a884e2e.mp3', 215),
    ('给水管', 'gěi shuǐ guǎn', 'ống cấp nước', '给水管安装时要注意接口密封，防止漏水。', 'gěi shuǐ guǎn ān zhuāng shí yào zhù yì jiē kǒu mì fēng, fáng zhǐ lòu shuǐ.', 'Khi lắp ống cấp nước cần chú ý kín khít các mối nối để tránh rò rỉ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-50a55e59df935592c4822ec5.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-a3681dafbcfec68b547ffce9.mp3', 216),
    ('排水管', 'pái shuǐ guǎn', 'ống thoát nước', '排水管铺设要保证坡度，确保雨水顺畅排出。', 'pái shuǐ guǎn pū shè yào bǎo zhèng pō dù, què bǎo yǔ shuǐ shùn chàng pái chū.', 'Lắp đặt ống thoát nước phải đảm bảo độ dốc để nước mưa chảy thông suốt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-9f4afeefb1ab198faa0e00e9.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-a6a0bdc86136e9fc7ffcbc39.mp3', 217),
    ('水阀', 'shuǐ fá', 'van nước', '施工中检查各水阀功能是否正常，防止漏水。', 'shī gōng zhōng jiǎn chá gè shuǐ fá gōng néng shì fǒu zhèng cháng, fáng zhǐ lòu shuǐ.', 'Trong thi công cần kiểm tra chức năng các van nước có hoạt động bình thường không để tránh rò rỉ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-fba029af62c3886128b50905.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-055dd80914fd1357e1864d36.mp3', 218),
    ('水泵', 'shuǐ bèng', 'bơm nước', '水泵启动后，要及时监测运行压力确保设备正常。', 'shuǐ bèng qǐ dòng hòu, yào jí shí jiān cè yùn xíng yā lì què bǎo shè bèi zhèng cháng.', 'Khi bơm nước khởi động phải kịp thời kiểm tra áp suất vận hành để đảm bảo thiết bị bình thường.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-d969d7c054625f52deeea217.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-4def22d588743430d1944b6c.mp3', 219),
    ('空调系统', 'kōng tiáo xì tǒng', 'hệ thống điều hòa không khí', '空调系统安装完成后，需做性能测试确保效果。', 'kōng tiáo xì tǒng ān zhuāng wán chéng hòu, xū zuò xìng néng cè shì què bǎo xiào guǒ.', 'Sau khi lắp đặt hệ thống điều hòa cần thử nghiệm hiệu năng để đảm bảo hiệu quả.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-a8ed86a5e028e4090a80a3f1.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-7f499db191cd41af75463fbe.mp3', 220),
    ('风管', 'fēng guǎn', 'ống gió', '风管连接必须密封，避免冷气外泄影响制冷效果。', 'fēng guǎn lián jiē bì xū mì fēng, bì miǎn lěng qì wài xiè yǐng xiǎng zhì lěng xiào guǒ.', 'Các mối nối ống gió phải kín để tránh khí lạnh thoát ra làm giảm hiệu quả làm lạnh.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-3b968080d39a22cbaa37f53b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-7bcee42fa4406cbf27d94621.mp3', 221),
    ('排风扇', 'pái fēng shàn', 'quạt thông gió', '排风扇安装位置应保证室内空气流通良好。', 'pái fēng shàn ān zhuāng wèi zhì yīng bǎo zhèng shì nèi kōng qì liú tōng liáng hǎo.', 'Vị trí lắp quạt thông gió phải đảm bảo không khí trong phòng lưu thông tốt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-efe210aaebd527faf1c078db.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-3d009f1ccce1b38eeb1781c6.mp3', 222),
    ('火灾报警器', 'huǒ zāi bào jǐng qì', 'đầu báo cháy', '火灾报警器应定期测试，保证火情时能及时报警。', 'huǒ zāi bào jǐng qì yīng dìng qī cè shì, bǎo zhèng huǒ qíng shí néng jí shí bào jǐng.', 'Đầu báo cháy cần được kiểm tra định kỳ để đảm bảo phát hiện cháy kịp thời.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-4c829169105b3a18930c66e3.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-e5306ca9f8af6638ed62630c.mp3', 223),
    ('消防管道', 'xiāo fáng guǎn dào', 'ống chữa cháy', '消防管道铺设需符合设计规范并严密连接。', 'xiāo fáng guǎn dào pū shè xū fú hé shè jì guī fàn bìng yán mì lián jiē.', 'Lắp đặt ống chữa cháy phải tuân theo quy chuẩn thiết kế và nối kín chắn chắn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-d47e84beabdeffb17338d248.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-66bb15953e280c271c97bf85.mp3', 224),
    ('压力试验', 'yā lì shì yàn', 'thử áp lực', '给水管道安装后，必须进行压力试验确认无泄漏。', 'gěi shuǐ guǎn dào ān zhuāng hòu, bì xū jìn xíng yā lì shì yàn què rèn wú xiè lòu.', 'Sau khi lắp đặt đường ống cấp nước cần thử áp lực để xác định không rò rỉ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-6446551acb667b5e3dc3ee60.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-94d5c10319cad304df439c72.mp3', 225),
    ('电线桥架', 'diàn xiàn qiáo jià', 'máng cáp điện', '电线桥架必须牢固安装，避免电缆受力损坏。', 'diàn xiàn qiáo jià bì xū láo gù ān zhuāng, bì miǎn diàn lǎn shòu lì sǔn huài.', 'Máng cáp điện phải lắp đặt chắc chắn để tránh làm hỏng cáp điện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-6a05e4ebd43828631f477dfb.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-9f48c3b82dbdb202ab48be9a.mp3', 226),
    ('照明灯具', 'zhào míng dēng jù', 'đèn chiếu sáng', '施工现场安装照明灯具，保障夜间作业安全。', 'shī gōng xiàn chǎng ān zhuāng zhào míng dēng jù, bǎo zhàng yè jiān zuò yè ān quán.', 'Lắp đèn chiếu sáng tại công trường để đảm bảo an toàn làm việc ban đêm.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-4d5e12e29f0f8c06132ad819.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-0a55ed456b106d609e769236.mp3', 227),
    ('配电箱漏电保护器', 'pèi diàn xiāng lòu diàn bǎo hù qì', 'cầu dao chống rò điện trong tủ điện', '配电箱漏电保护器安装完毕后，需测试其灵敏度。', 'pèi diàn xiāng lòu diàn bǎo hù qì ān zhuāng wán bì hòu, xū cè shì qí líng mǐn dù.', 'Sau khi lắp cầu dao chống rò điện trong tủ điện cần thử độ nhạy của nó.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-74ea897e6c4cf13094088a4e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-f452f45af5e9b1ae0c22c968.mp3', 228),
    ('管件', 'guǎn jiàn', 'phụ kiện ống (co, tê, cút)', '检查管件连接处是否牢固，防止接口漏水。', 'jiǎn chá guǎn jiàn lián jiē chù shì fǒu láo gù, fáng zhǐ jiē kǒu lòu shuǐ.', 'Kiểm tra các mối nối phụ kiện ống có chắc chắn để tránh rò rỉ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-09383fb80f52783e4bbd1b98.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-41d83e0d40c2084066bfdef1.mp3', 229),
    ('水表', 'shuǐ biǎo', 'đồng hồ nước', '安装完毕后要校验水表读数准确无误。', 'ān zhuāng wán bì hòu yào jiào yàn shuǐ biǎo dú shù zhǔn què wú wù.', 'Sau khi lắp đặt đồng hồ nước cần kiểm tra số đo chính xác.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-47a218206bab32848dcac2d2.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-cdb20a8c52b521ac2af670aa.mp3', 230),
    ('空调管道', 'kōng tiáo guǎn dào', 'ống điều hòa', '空调管道铺设时要保持密封，防止冷媒泄漏。', 'kōng tiáo guǎn dào pū shè shí yào bǎo chí mì fēng, fáng zhǐ lěng méi xiè lòu.', 'Lắp đặt ống điều hòa phải giữ kín để ngăn chất làm lạnh bị thoát ra.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-a81a273739b48f2da994225d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-33ff3761441d5876b62d5042.mp3', 231),
    ('排气阀', 'pái qì fá', 'van xả khí', '排气阀设置在高处，确保管道内气体排出。', 'pái qì fá shè zhì zài gāo chù, què bǎo guǎn dào nèi qì tǐ pái chū.', 'Van xả khí được lắp ở vị trí cao để đảm bảo khí trong ống được thoát ra.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-78e013d59ced9958b961bb9b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-4fd8a9ee14d2815b1b260030.mp3', 232),
    ('管道支架', 'guǎn dào zhī jià', 'giá đỡ ống', '管道支架要安装牢固，防止管道松动影响系统运行。', 'guǎn dào zhī jià yào ān zhuāng láo gù, fáng zhǐ guǎn dào sōng dòng yǐng xiǎng xì tǒng yùn xíng.', 'Giá đỡ ống phải được lắp chắc chắn để tránh ống bị lỏng gây ảnh hưởng hệ thống.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-696f98978eecd4b07b607794.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-d4a62d7fbc75a3f55c4169e4.mp3', 233),
    ('冷凝水管', 'lěng níng shuǐ guǎn', 'ống thoát nước ngưng', '空调冷凝水管须通畅，防止水倒流造成损坏。', 'kōng tiáo lěng níng shuǐ guǎn xū tōng chàng, fáng zhǐ shuǐ dào liú zào chéng sǔn huài.', 'Ống thoát nước ngưng của điều hòa phải thông suốt để tránh nước chảy ngược gây hư hỏng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-b099e1d30aa8039786d34a73.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-49657c41bb5831a889f146b5.mp3', 234),
    ('消防水泵', 'xiāo fáng shuǐ bèng', 'bơm chữa cháy', '消防水泵启动正常，保证紧急情况下供水压力。', 'xiāo fáng shuǐ bèng qǐ dòng zhèng cháng, bǎo zhèng jǐn jí qíng kuàng xià gōng shuǐ yā lì.', 'Bơm chữa cháy hoạt động bình thường để đảm bảo áp lực nước khi khẩn cấp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-62945d4f2360dee80249459b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-b107790a1a4b5eda4d630930.mp3', 235),
    ('电气控制箱', 'diàn qì kòng zhì xiāng', 'hộp điều khiển điện', '电气控制箱内线路布置要规范以保证安全。', 'diàn qì kòng zhì xiāng nèi xiàn lù bù zhì yào guī fàn yǐ bǎo zhèng ān quán.', 'Việc bố trí đường dây trong hộp điều khiển điện phải đúng quy chuẩn để đảm bảo an toàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-286b9bf7b143a144d6b4128f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-fe8f520e7503ec6c7ef0cb7d.mp3', 236),
    ('管道疏通机', 'guǎn dào shū tōng jī', 'máy thông tắc ống', '管道疏通机用于清理排水管道内部堵塞。', 'guǎn dào shū tōng jī yòng yú qīng lǐ pái shuǐ guǎn dào nèi bù dǔ sè.', 'Máy thông tắc ống được dùng để làm sạch các tắc nghẽn bên trong ống thoát nước.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-6da2a1389decc496ed3a71ee.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-feb69629814c67cf1fdce0e9.mp3', 237),
    ('数据线', 'shù jù xiàn', 'dây cáp tín hiệu truyền dữ liệu', '数据线连接到智能控制系统，实现远程监控。', 'shù jù xiàn lián jiē dào zhì néng kòng zhì xì tǒng, shí xiàn yuǎn chéng jiān kòng.', 'Dây cáp tín hiệu nối vào hệ thống điều khiển thông minh giúp giám sát từ xa.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-8d112ac9b899713f8ecedd3d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-aa96433c14edbbf51a20a8ca.mp3', 238),
    ('冷热水管', 'lěng rè shuǐ guǎn', 'ống nước nóng và lạnh', '冷热水管道安装要分区布置，方便维修及检测。', 'lěng rè shuǐ guǎn dào ān zhuāng yào fēn qū bù zhì, fāng biàn wéi xiū jí jiǎn cè.', 'Lắp đặt ống nước nóng lạnh cần bố trí phân vùng để dễ sửa chữa và kiểm tra.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-14c314d480df26e4a610a582.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-4ed8fd8305e063a0027a4611.mp3', 239),
    ('电缆桥架', 'diàn lǎn qiáo jià', 'máng cáp điện', '电缆桥架布线整齐，便于后期维护和检查。', 'diàn lǎn qiáo jià bù xiàn zhěng qí, biàn yú hòu qī wéi hù hé jiǎn chá.', 'Máng cáp điện phải được sắp xếp ngăn nắp để thuận tiện bảo trì và kiểm tra sau này.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-304a2e2f75607e7187abe96b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-c9ee133e04d7748809921e8c.mp3', 240),
    ('瓷砖铺贴', 'cí zhuān pū tiē', 'ốp gạch men', '施工员严格检查瓷砖铺贴的缝隙是否均匀整齐。', 'shī gōng yuán yán gé jiǎn chá cí zhuān pū tiē de fèng xì shì fǒu jūn yún zhěng qí.', 'Nhân viên thi công kiểm tra nghiêm ngặt khe ốp gạch men có đều và đẹp không.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-c635fa078eba9124bc55df61.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-ac50fc2889c5d5fd00e3abed.mp3', 241),
    ('地面找平', 'dì miàn zhǎo píng', 'lát nền, làm phẳng mặt sàn', '先进行地面找平，确保后续铺装材料平整牢固。', 'xiān jìn xíng dì miàn zhǎo píng, què bǎo hòu xù pū zhuāng cái liào píng zhěng láo gù.', 'Trước tiên làm phẳng mặt sàn, đảm bảo vật liệu lát nền sau đó được phẳng và chắc chắn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-877e1018cd9c499d190f44bb.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-d725560cbcfe6b339b275e3b.mp3', 242),
    ('勾缝剂', 'gōu fèng jì', 'chất chà ron gạch', '使用优质勾缝剂填充瓷砖缝隙，防止水渗透。', 'shǐ yòng yōu zhì gōu fèng jì tián chōng cí zhuān fèng xì, fáng zhǐ shuǐ shèn tòu.', 'Sử dụng chất chà ron cao cấp để trám khe gạch, tránh nước thấm.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-8e8e1d7a3c0bd7c47d916737.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-8fca5e626f8199ddaeea6cb6.mp3', 243),
    ('腻子粉', 'nì zi fěn', 'bột bả tường', '墙面刷腻子粉后需打磨，保证表面平整。', 'qiáng miàn shuā nì zi fěn hòu xū dǎ mó, bǎo zhèng biǎo miàn píng zhěng.', 'Sau khi quét bột bả tường cần mài nhẵn để đảm bảo bề mặt phẳng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-03706cea52316735ac729016.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-90792be553f7ad5d7d49fd33.mp3', 244),
    ('底漆涂刷', 'dǐ qī tú shuā', 'sơn lót', '在施工前先进行底漆涂刷，提高附着力。', 'zài shī gōng qián xiān jìn xíng dǐ qī tú shuā, tí gāo fù zhuó lì.', 'Trước khi thi công tiến hành sơn lót để tăng độ bám dính.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-7558263058967c702c47f845.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-d3e593be815acef6d185232e.mp3', 245),
    ('面漆施工', 'miàn qī shī gōng', 'sơn phủ', '面漆施工应均匀涂抹，防止色差明显。', 'miàn qī shī gōng yīng jūn yún tú mǒ, fáng zhǐ sè chā míng xiǎn.', 'Sơn phủ cần quét đều để tránh sự khác màu rõ rệt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-f25ea9a65e44e2b3f972e311.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-68dfb1f71f7dae4537a25b78.mp3', 246),
    ('石膏吊顶', 'shí gāo diào dǐng', 'trần thạch cao', '石膏吊顶安装后需检查平整度和接缝处理。', 'shí gāo diào dǐng ān zhuāng hòu xū jiǎn chá píng zhěng dù hé jiē fèng chǔ lǐ.', 'Sau khi lắp đặt trần thạch cao phải kiểm tra độ phẳng và xử lý mối nối.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-f6f29d75fb6841dad7cb9973.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-3180629690fe4053d02b3b84.mp3', 247),
    ('门扇安装', 'mén shàn ān zhuāng', 'lắp cửa cánh cửa', '门扇安装后需调整铰链保证开关灵活。', 'mén shàn ān zhuāng hòu xū tiáo zhěng jiǎo lián bǎo zhèng kāi guān líng huó.', 'Lắp cửa cánh xong cần điều chỉnh bản lề để cửa mở đóng linh hoạt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-d527d552f74809f6c611f57c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-d59e3d36d46b857147e1b5cf.mp3', 248),
    ('玻璃安装', 'bō li ān zhuāng', 'lắp đặt kính', '施工人员仔细测量尺寸，确保玻璃安装精准。', 'shī gōng rén yuán zǐ xì cè liáng chǐ cùn, què bǎo bō li ān zhuāng jīng zhǔn.', 'Nhân viên thi công đo kích thước cẩn thận để lắp kính chính xác.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-9800fb09ffb95dae509db52f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-b17dce995f73f19d0ab07869.mp3', 249),
    ('防水涂料', 'fáng shuǐ tú liào', 'chất chống thấm', '防水涂料需要均匀刷涂，避免渗漏隐患。', 'fáng shuǐ tú liào xū yào jūn yún shuā tú, bì miǎn shèn lòu yǐn huàn.', 'Chất chống thấm cần quét đều để tránh nguy cơ thấm nước.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-8b8cfacdda357ed3e4137f91.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-3ad69836efa2771aae704c5c.mp3', 250),
    ('平整度检测', 'píng zhěng dù jiǎn cè', 'kiểm tra độ phẳng bề mặt', '完工后进行平整度检测，确保符合设计要求。', 'wán gōng hòu jìn xíng píng zhěng dù jiǎn cè, què bǎo fú hé shè jì yāo qiú.', 'Hoàn thành xong tiến hành kiểm tra độ phẳng để đảm bảo đúng yêu cầu thiết kế.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-58909a4f922c8f1eef4976e1.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-c057e4823474595009871bd2.mp3', 251),
    ('蜂窝麻面', 'fēng wō má miàn', 'rỗ bê tông bề mặt', '如果出现蜂窝麻面，应及时处理，保证表面质量。', 'rú guǒ chū xiàn fēng wō má miàn, yīng jí shí chǔ lǐ, bǎo zhèng biǎo miàn zhì liàng.', 'Nếu bề mặt bê tông bị rỗ cần xử lý kịp thời để đảm bảo chất lượng bề mặt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-9349e8217e2982d70fef504c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-d048399b905bb773428c5cc3.mp3', 252),
    ('尺寸偏差', 'chǐ cùn piān chā', 'sai lệch kích thước', '施工中出现尺寸偏差会影响后续安装工序。', 'shī gōng zhōng chū xiàn chǐ cùn piān chā huì yǐng xiǎng hòu xù ān zhuāng gōng xù.', 'Kích thước sai lệch trong thi công sẽ ảnh hưởng đến các bước lắp đặt tiếp theo.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-07f38c51b1edf7e446742c0e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-032b42bce4967c6e8071afe3.mp3', 253),
    ('吸水率', 'xī shuǐ lǜ', 'tỷ lệ hút nước (gạch, vật liệu)', '测试瓷砖的吸水率以判断其防潮性能。', 'cè shì cí zhuān de xī shuǐ lǜ yǐ pàn duàn qí fáng cháo xìng néng.', 'Kiểm tra tỷ lệ hút nước của gạch để đánh giá khả năng chống ẩm.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-669e9f704914f529247a84ee.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-9f73d9c696f43e556c80aee2.mp3', 254),
    ('涂刷均匀', 'tú shuā jūn yún', 'quét sơn đều', '涂刷过程中应确保涂刷均匀，无遗漏。', 'tú shuā guò chéng zhōng yīng què bǎo tú shuā jūn yún, wú yí lòu.', 'Quá trình quét sơn phải đảm bảo đều và không bỏ sót.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-12f46acb05791602357cbebc.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-58eb5f5257fc72174f6dbc67.mp3', 255),
    ('缝隙清理', 'fèng xì qīng lǐ', 'làm sạch khe hở trước khi chà ron', '在使用勾缝剂前必须进行缝隙清理，保证粘结效果。', 'zài shǐ yòng gōu fèng jì qián bì xū jìn xíng fèng xì qīng lǐ, bǎo zhèng zhān jié xiào guǒ.', 'Trước khi dùng chất chà ron phải làm sạch khe hở để đảm bảo kết dính tốt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-e2e7ecc8a40194229c9f32f5.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-9ac8c658e154717e216a6d2f.mp3', 256),
    ('表面打磨', 'biǎo miàn dǎ mó', 'mài nhẵn bề mặt', '墙面腻子粉干燥后需要进行表面打磨。', 'qiáng miàn nì zi fěn gān zào hòu xū yào jìn xíng biǎo miàn dǎ mó.', 'Sau khi bột bả tường khô cần mài nhẵn bề mặt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-39b193200abd1f57aa0e8663.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-46a2429adc1a005285951ba2.mp3', 257),
    ('挂件安装', 'guà jiàn ān zhuāng', 'lắp đặt phụ kiện (cửa, kính)', '完成门框后进行挂件安装，确保固定牢靠。', 'wán chéng mén kuàng hòu jìn xíng guà jiàn ān zhuāng, què bǎo gù dìng láo kào.', 'Hoàn thành khung cửa rồi tiến hành lắp phụ kiện để đảm bảo chắc chắn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-ffe893e225785e14bcb07d79.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-c221b76c36dbaa75e6f659ec.mp3', 258),
    ('防潮处理', 'fáng cháo chǔ lǐ', 'xử lý chống ẩm', '墙体防潮处理是保证涂料不起泡的关键。', 'qiáng tǐ fáng cháo chǔ lǐ shì bǎo zhèng tú liào bù qǐ pào de guān jiàn.', 'Xử lý chống ẩm tường là yếu tố then chốt để sơn không bị phồng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-5eabb493a8ca918a396aec77.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-6fef97f12ff1754d8bd10bf1.mp3', 259),
    ('接缝处理', 'jiē fèng chǔ lǐ', 'xử lý mối nối, khe hở', '石膏板接缝处理不当会造成墙面开裂。', 'shí gāo bǎn jiē fèng chǔ lǐ bù dàng huì zào chéng qiáng miàn kāi liè.', 'Xử lý mối nối thạch cao không đúng sẽ làm tường bị nứt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-3b30cadc52356c35933d6edf.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-0bde6836d35ed0b92a303f23.mp3', 260),
    ('涂层厚度', 'tú céng hòu dù', 'độ dày lớp sơn', '测量涂层厚度确保达到设计标准要求。', 'cè liáng tú céng hòu dù què bǎo dá dào shè jì biāo zhǔn yāo qiú.', 'Đo độ dày lớp sơn để đảm bảo đạt tiêu chuẩn thiết kế.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-4128a6527a8946e7e00b08f8.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-12d95a5fc7bf00833ced2154.mp3', 261),
    ('验收标准', 'yàn shōu biāo zhǔn', 'tiêu chuẩn nghiệm thu', '所有完工项目必须符合验收标准才允许交付使用。', 'suǒ yǒu wán gōng xiàng mù bì xū fú hé yàn shōu biāo zhǔn cái yǔn xǔ jiāo fù shǐ yòng.', 'Tất cả các hạng mục hoàn thiện phải đạt tiêu chuẩn nghiệm thu mới được bàn giao.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-df431cfed98e5f242c6284c5.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-a9e7de6551801a4a3bf7889b.mp3', 262),
    ('施工进度控制', 'shī gōng jìn dù kòng zhì', 'kiểm soát tiến độ thi công', '项目经理严格进行施工进度控制，避免工期延误。', 'xiàng mù jīng lǐ yán gé jìn xíng shī gōng jìn dù kòng zhì, bì miǎn gōng qī yán wù.', 'Quản lý dự án nghiêm túc kiểm soát tiến độ thi công để tránh trì hoãn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-03234d16fd499fa41d8487e2.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-2283456192bc62a0320bca28.mp3', 263),
    ('质量验收', 'zhì liàng yàn shōu', 'kiểm tra nghiệm thu chất lượng', '完工后应进行质量验收，确保符合设计要求。', 'wán gōng hòu yīng jìn xíng zhì liàng yàn shōu, què bǎo fú hé shè jì yāo qiú.', 'Hoàn thành công việc phải kiểm tra nghiệm thu chất lượng, đảm bảo theo thiết kế.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-2ee6b1b555b6058bff91bfdc.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-806901a0b5b528499f09f99f.mp3', 264),
    ('补强处理', 'bǔ qiáng chǔ lǐ', 'xử lý gia cố, sửa chữa khuyết điểm', '对发现的结构缺陷进行补强处理，保证安全性。', 'duì fā xiàn de jié gòu quē xiàn jìn xíng bǔ qiáng chǔ lǐ, bǎo zhèng ān quán xìng.', 'Xử lý gia cố các khuyết điểm kết cấu phát hiện được để đảm bảo an toàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-4a396b13c8da7eff85c95f5d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-f051e8084347f6c221572043.mp3', 265),
    ('防霉处理', 'fáng méi chǔ lǐ', 'xử lý chống mốc', '卫生间墙面需做防霉处理，延长涂层寿命。', 'wèi shēng jiān qiáng miàn xū zuò fáng méi chǔ lǐ, yán cháng tú céng shòu mìng.', 'Tường nhà vệ sinh cần xử lý chống mốc để kéo dài tuổi thọ lớp sơn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-8e67240c4877f69b7195943e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-f31809ddc99607a31d98f42c.mp3', 266),
    ('颜色匹配', 'yán sè pǐ pèi', 'phối màu, khớp màu sơn', '面漆颜色匹配需与设计图纸保持一致。', 'miàn qī yán sè pǐ pèi xū yǔ shè jì tú zhǐ bǎo chí yī zhì.', 'Màu sơn phủ phải phối hợp đúng với bản vẽ thiết kế.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-51757df74a0fe9cb659e56ac.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-98a65dcca10d0c9af70baae3.mp3', 267),
    ('防火涂层', 'fáng huǒ tú céng', 'lớp sơn chống cháy', '石膏板吊顶需喷涂防火涂层，符合消防要求。', 'shí gāo bǎn diào dǐng xū pēn tú fáng huǒ tú céng, fú hé xiāo fáng yāo qiú.', 'Trần thạch cao phải phủ lớp sơn chống cháy để đáp ứng tiêu chuẩn phòng cháy.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-f56deb3a0f6919c4f7bb3c1a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-60d0bf9b223f51acd4098b85.mp3', 268),
    ('修补裂缝', 'xiū bǔ liè fèng', 'Sửa chữa vết nứt, khuyết tật hoàn thiện', '质检员发现墙角裂缝后，要求及时进行修补裂缝以保证质量。', 'zhì jiǎn yuán fā xiàn qiáng jiǎo liè fèng hòu, yāo qiú jí shí jìn xíng xiū bǔ liè fèng yǐ bǎo zhèng zhì liàng.', 'Sau khi phát hiện vết nứt ở góc tường, nhân viên kiểm tra chất lượng yêu cầu sửa chữa kịp thời để đảm bảo chất lượng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-c867316f98226d0288342485.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-a967b876f13b7cd99071eeb7.mp3', 269),
    ('瓷砖勾缝剂', 'cí zhuān gōu fèng jì', 'Vật liệu dùng để chà ron giữa các viên gạch ốp', '施工队员正在用瓷砖勾缝剂仔细填补地砖缝隙，保证美观和防水。', 'shī gōng duì yuán zhèng zài yòng cí zhuān gōu fèng jì zǐ xì tián bǔ dì zhuān fèng xì, bǎo zhèng měi guān hé fáng shuǐ.', 'Đội thi công đang dùng keo chà ron gạch để cẩn thận lấp các khe gạch nền, đảm bảo tính thẩm mỹ và chống thấm.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-166907d03dd1d93566370a3c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-e1536609efa2ebb7ba677ce6.mp3', 270),
    ('安全帽', 'ānquán mào', 'mũ bảo hộ', '施工人员必须正确佩戴安全帽以防止头部受伤。', 'shīgōng rényuán bìxū zhèngquè pèidài ānquán mào yǐ fángzhǐ tóubù shòushāng.', 'Công nhân thi công phải đội mũ bảo hộ đúng cách để tránh bị thương đầu.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-fcbe7863fb147205b5d70d55.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-d8b6461ac416e51f3d13596d.mp3', 271),
    ('安全带', 'ānquán dài', 'dây an toàn', '高空作业时必须系好安全带确保人身安全。', 'gāokōng zuòyè shí bìxū xì hǎo ānquán dài quèbǎo rénshēn ānquán.', 'Khi làm việc trên cao phải thắt dây an toàn để bảo đảm an toàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-18d8ab054b71ebb37281acd6.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-12e852f9b9c15d31704cf957.mp3', 272),
    ('安全鞋', 'ānquán xié', 'giày bảo hộ', '施工现场要求穿戴符合标准的安全鞋防止足部受伤。', 'shīgōng xiànchǎng yāoqiú chuāndài fúhé biāozhǔn de ānquán xié fángzhǐ zúbù shòushāng.', 'Công trường yêu cầu mang giày bảo hộ đạt tiêu chuẩn để tránh thương tích chân.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-f943053efdac700eedf8a1f6.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-f3f44aaad88f18defeca2951.mp3', 273),
    ('安全护栏', 'ānquán hùlán', 'lan can an toàn', '施工平台边缘安装安全护栏防止人员坠落事故发生。', 'shīgōng píngtái biānyuán ānzhuāng ānquán hùlán fángzhǐ rényuán zhuìluò shìgù fāshēng.', 'Lắp đặt lan can an toàn ở mép sàn thi công để tránh tai nạn rơi người.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-c254d05b031377fb3bc85f92.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-e922acf8b0107fabd3810064.mp3', 274),
    ('安全网', 'ānquán wǎng', 'lưới an toàn', '塔吊周围设置安全网防止物体坠落造成伤害。', 'tǎ diào zhōuwéi shèzhì ānquán wǎng fángzhǐ wùtǐ zhuìluò zàochéng shānghài.', 'Xung quanh cẩu tháp lắp đặt lưới an toàn để ngăn ngừa vật rơi gây thương tích.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-8f82b4ee1345d321b95e84b1.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-b7c4a5444cf54723d4151937.mp3', 275),
    ('警示标志', 'jǐngshì biāozhì', 'biển cảnh báo', '施工现场入口处设置明显的警示标志提醒注意安全。', 'shīgōng xiànchǎng rùkǒu chù shèzhì míngxiǎn de jǐngshì biāozhì tíxǐng zhùyì ānquán.', 'Cổng công trường đặt biển cảnh báo rõ ràng nhắc nhở chú ý an toàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-bd9fd8c9c5c5410e79fadb2c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-465a7519f2387da696ebfa40.mp3', 276),
    ('高空作业', 'gāokōng zuòyè', 'làm việc trên cao', '高空作业必须严格遵守安全操作规程避免事故发生。', 'gāokōng zuòyè bìxū yángé zūnshǒu ānquán cāozuò guīchéng bìmiǎn shìgù fāshēng.', 'Làm việc trên cao phải nghiêm túc tuân thủ quy trình an toàn để tránh tai nạn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-94c2b656eec943b54fe233bc.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-7d783e69c510a21c2f05ab77.mp3', 277),
    ('受限空间', 'shòuxiàn kōngjiān', 'không gian hạn chế', '进入受限空间前必须办理相关作业许可证确保安全。', 'jìnrù shòuxiàn kōngjiān qián bìxū bànlǐ xiāngguān zuòyè xǔkě zhèng quèbǎo ānquán.', 'Trước khi vào không gian hạn chế phải làm giấy phép làm việc để đảm bảo an toàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-b399cb6603eb311677f5f058.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-dabd93d207fae16ac477a544.mp3', 278),
    ('作业许可证', 'zuòyè xǔkě zhèng', 'giấy phép làm việc', '高危作业开始前必须取得有效的作业许可证。', 'gāo wēi zuòyè kāishǐ qián bìxū qǔdé yǒuxiào de zuòyè xǔkě zhèng.', 'Trước khi bắt đầu công việc nguy hiểm cao phải có giấy phép làm việc hợp lệ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-beb0d6b3c1d0984e4419dfad.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-01b0db87398e1b113b22401c.mp3', 279),
    ('施工进度计划', 'shīgōng jìndù jìhuà', 'kế hoạch tiến độ thi công', '项目部制定详细施工进度计划以保证按期完成任务。', 'xiàngmù bù zhìdìng xiángxì shīgōng jìndù jìhuà yǐ bǎozhèng ànqī wánchéng rènwu.', 'Bộ phận dự án lập kế hoạch tiến độ thi công chi tiết để đảm bảo hoàn thành đúng hạn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-b221629d4b247e59e5dd2ed7.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-86a5dd78f43fcac61006af62.mp3', 280),
    ('完成工程量', 'wánchéng gōngchéng liàng', 'khối lượng hoàn thành', '每天统计完成工程量以便及时调整施工安排。', 'měitiān tǒngjì wánchéng gōngchéng liàng yǐbiàn jíshí tiáozhěng shīgōng ānpái.', 'Mỗi ngày tổng kết khối lượng hoàn thành để điều chỉnh lịch thi công kịp thời.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-49190d3d28901b995cf68c94.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-1b5cea5471b9b2a16adec7e2.mp3', 281),
    ('进度延误', 'jìndù yánwù', 'chậm tiến độ', '由于材料短缺导致施工进度延误，需要及时协调解决。', 'yóuyú cáiliào duǎnquē dǎozhì shīgōng jìndù yánwù, xūyào jíshí xiétiáo jiějué.', 'Do thiếu vật liệu gây chậm tiến độ thi công, cần phối hợp giải quyết kịp thời.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-22b5b57680c92ea3dfb75e6e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-bfd4154b9664f65c029fb7d8.mp3', 282),
    ('工程验收', 'gōngchéng yànshōu', 'nghiệm thu công trình', '完成施工后需组织相关人员进行工程验收确认质量。', 'wánchéng shīgōng hòu xū zǔzhī xiāngguān rényuán jìnxíng gōngchéng yànshōu quèrèn zhìliàng.', 'Sau khi hoàn thành thi công phải tổ chức nghiệm thu công trình để kiểm tra chất lượng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-764d2f28a3ecd976e83bd7c8.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-0ad357ee291d24408246aefc.mp3', 283),
    ('竣工验收', 'jùngōng yànshōu', 'nghiệm thu hoàn thành', '项目竣工后进行竣工验收确认符合设计要求。', 'xiàngmù jùngōng hòu jìnxíng jùngōng yànshōu quèrèn fúhé shèjì yāoqiú.', 'Dự án hoàn thành tiến hành nghiệm thu hoàn thành để xác nhận đạt yêu cầu thiết kế.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-4230f10b26c9a05732e0ca34.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-bd971b05eaa260a008978285.mp3', 284),
    ('工程交付', 'gōngchéng jiāofù', 'bàn giao công trình', '验收合格后及时进行工程交付并完成相关手续。', 'yànshōu hégé hòu jíshí jìnxíng gōngchéng jiāofù bìng wánchéng xiāngguān shǒuxù.', 'Sau khi nghiệm thu đạt yêu cầu tiến hành bàn giao công trình kèm thủ tục liên quan.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-fb3dd365c7ae3e75e078f169.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-15605fe1319e6792310a01ae.mp3', 285),
    ('防护栏杆', 'fánghù lángān', 'lan can bảo hộ', '施工现场周边安装防护栏杆确保人员安全。', 'shīgōng xiànchǎng zhōubiān ānzhuāng fánghù lángān quèbǎo rényuán ānquán.', 'Lắp đặt lan can bảo hộ quanh công trường để đảm bảo an toàn cho người.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-65a7f6a071bb022b94444b5c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-64492d9d4d54bbe18f719aa1.mp3', 286),
    ('安全检查', 'ānquán jiǎnchá', 'kiểm tra an toàn', '每日施工前必须进行安全检查排除潜在隐患。', 'měi rì shīgōng qián bìxū jìnxíng ānquán jiǎnchá páichú qiánzài yǐnhuàn.', 'Mỗi ngày trước thi công phải kiểm tra an toàn để loại bỏ nguy cơ tiềm tàng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-b16cf917405dd42345114d05.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-eea79f866e56a75f07aece39.mp3', 287),
    ('安全教育培训', 'ānquán jiàoyù péixùn', 'đào tạo giáo dục an toàn', '新员工入场前必须参加安全教育培训了解施工规范。', 'xīn yuángōng rùchǎng qián bìxū cānjiā ānquán jiàoyù péixùn liǎojiě shīgōng guīfàn.', 'Nhân viên mới vào công trường phải tham gia đào tạo an toàn để hiểu quy định thi công.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-27b9ad0a9d85b17c5530a572.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-7c2fe9cebcb0ef6426d85240.mp3', 288),
    ('紧急疏散预案', 'jǐnjí shūsàn yù''àn', 'kế hoạch sơ tán khẩn cấp', '制定紧急疏散预案保证突发情况人员安全撤离。', 'zhìdìng jǐnjí shūsàn yù''àn bǎozhèng tūfā qíngkuàng rényuán ānquán chèlí.', 'Lập kế hoạch sơ tán khẩn cấp để đảm bảo an toàn thoát hiểm khi có sự cố.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-d5b23bf772fc4ab5340225d9.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-688e6b997d192398f9de9a34.mp3', 289),
    ('考勤管理', 'kǎoqín guǎnlǐ', 'quản lý chấm công', '施工现场实行严格考勤管理确保人员出勤率。', 'shīgōng xiànchǎng shíxíng yángé kǎoqín guǎnlǐ quèbǎo rényuán chūqín lǜ.', 'Công trường thi công áp dụng quản lý chấm công nghiêm ngặt để đảm bảo tỷ lệ chuyên cần.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-be24680b1bc5e3241ee36183.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-9c4d95bcb14f47af56baa32b.mp3', 290),
    ('现场交底', 'xiànchǎng jiāodǐ', 'bàn giao công tác tại hiện trường', '班组长组织现场交底确保每个人了解施工要求。', 'bānzǔ zhǎng zǔzhī xiànchǎng jiāodǐ quèbǎo měi gèrén liǎojiě shīgōng yāoqiú.', 'Tổ trưởng tổ chức bàn giao công tác tại hiện trường để mọi người hiểu rõ yêu cầu thi công.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-a52ad0b9f5a4137302fcc9bc.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-071757f2e7e58e6a7da39cdc.mp3', 291),
    ('隐患排查', 'yǐnhuàn páichá', 'kiểm tra tiềm ẩn nguy hiểm', '定期开展隐患排查及时发现并整改安全问题。', 'dìngqī kāizhǎn yǐnhuàn páichá jíshí fāxiàn bìng zhěnggǎi ānquán wèntí.', 'Thường xuyên kiểm tra tiềm ẩn nguy hiểm để phát hiện và khắc phục sự cố an toàn kịp thời.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-ace57e695c2e11a00bccc40d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-6b61b1403ba96d0f2fc25b42.mp3', 292),
    ('安全文明施工', 'ānquán wénmíng shīgōng', 'thi công an toàn văn minh', '要求所有施工人员遵守安全文明施工规范保障施工环境。', 'yāoqiú suǒyǒu shīgōng rényuán zūnshǒu ānquán wénmíng shīgōng guīfàn bǎozhàng shīgōng huánjìng.', 'Yêu cầu tất cả công nhân thi công tuân thủ quy định thi công an toàn văn minh để bảo vệ môi trường thi công.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-361bd86da8a4bb711530ecca.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-9c5691df192c6c91873e10fb.mp3', 293),
    ('延期申请', 'yánqī shēnqǐng', 'đơn xin gia hạn', '因特殊原因施工单位提交延期申请争取合理延长工期。', 'yīn tèshū yuányīn shīgōng dānwèi tíjiāo yánqī shēnqǐng zhēngqǔ hélǐ yáncháng gōngqī.', 'Do lý do đặc biệt, đơn vị thi công nộp đơn xin gia hạn để được kéo dài thời gian hợp lý.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-c18e284875e98c7c0cbf6688.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-99b6a02615e840936e3dc451.mp3', 294),
    ('现场验收', 'xiànchǎng yànshōu', 'nghiệm thu tại hiện trường', '验收人员现场验收材料质量确保符合技术要求。', 'yànshōu rényuán xiànchǎng yànshōu cáiliào zhìliàng quèbǎo fúhé jìshù yāoqiú.', 'Nhân viên nghiệm thu kiểm tra nghiệm thu tại hiện trường chất lượng vật liệu để đảm bảo đạt kỹ thuật.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-b14c275277eb41e44294f5e0.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-883d19affa0947dc2cd1be0e.mp3', 295),
    ('施工交接', 'shīgōng jiāojiē', 'bàn giao thi công', '施工班组完成后及时进行施工交接保证工作的连续性。', 'shīgōng bānzǔ wánchéng hòu jíshí jìnxíng shīgōng jiāojiē bǎozhèng gōngzuò de liánxù xìng.', 'Tổ thi công hoàn thành công việc phải bàn giao thi công kịp thời để bảo đảm tính liên tục.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-2467343a00365b3b0fd76b63.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-2a859fd0385eab0ab1deeac9.mp3', 296),
    ('安全责任制', 'ānquán zérèn zhì', 'chế độ trách nhiệm an toàn', '实行安全责任制明确各岗位的安全职责。', 'shíxíng ānquán zérèn zhì míngquè gè gǎngwèi de ānquán zhízé.', 'Thực hiện chế độ trách nhiệm an toàn để xác định rõ nhiệm vụ an toàn của từng vị trí.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-6417bf882e716a1938bf3cab.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-ea3f5708fc8306f9d1294522.mp3', 297),
    ('应急预案', 'yìngjí yù''àn', 'kế hoạch ứng phó khẩn cấp', '项目制定详尽应急预案应对突发安全事件。', 'xiàngmù zhìdìng xiángjìn yìngjí yù''àn yìngduì tūfā ānquán shìjiàn.', 'Dự án xây dựng kế hoạch ứng phó khẩn cấp đầy đủ để xử lý sự cố an toàn bất ngờ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-33a9d9b25ea11b32e815599b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-609b4900e9b50d4485b8027d.mp3', 298),
    ('高处作业许可证', 'gāochù zuòyè xǔkězhèng', 'giấy phép làm việc trên cao', '施工人员进入作业区前必须确认高处作业许可证有效。', 'Shīgōng rényuán jìnrù zuòyèqū qián bìxū quèrèn gāochù zuòyè xǔkězhèng yǒuxiào.', 'Trước khi vào khu vực làm việc, nhân viên thi công phải xác nhận giấy phép làm việc trên cao còn hiệu lực.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-c664185d77bf9f488ccbdda4.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-b5b13f4d8199c69db96d0492.mp3', 299),
    ('临边防护', 'línbiān fánghù', 'biện pháp bảo vệ mép sàn', '楼层施工前要检查所有临边防护是否牢固。', 'Lóucéng shīgōng qián yào jiǎnchá suǒyǒu línbiān fánghù shìfǒu láogù.', 'Trước khi thi công tầng, cần kiểm tra mọi biện pháp bảo vệ mép sàn có chắc chắn hay không.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/word-460c395353e0d4cede7dea50.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xay-dung-cong-trinh-300-tu/sentence-6885a576e50661ffb100cdcf.mp3', 300)
) as card(
  chinese,
  pinyin,
  meaning_vi,
  example_cn,
  example_pinyin,
  example_vi,
  word_audio_url,
  sentence_audio_url,
  position
)
on conflict (template_deck_id, chinese) do update
set
  pinyin = excluded.pinyin,
  meaning_vi = excluded.meaning_vi,
  example_cn = excluded.example_cn,
  example_pinyin = excluded.example_pinyin,
  example_vi = excluded.example_vi,
  word_audio_url = excluded.word_audio_url,
  sentence_audio_url = excluded.sentence_audio_url,
  position = excluded.position;

delete from public.template_cards
where template_deck_id = (
